import React, { useState } from "react";
import { Container, TextField, Button, Typography, Box, Paper, IconButton, InputAdornment, Checkbox, FormControlLabel, AppBar, Toolbar } from "@mui/material";
import { Visibility, VisibilityOff } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const Login = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    regNumber: "",
    password: "",
    showPassword: false,
    rememberMe: false,
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({ ...formData, [name]: type === "checkbox" ? checked : value });
    setErrors({ ...errors, [name]: value.trim() ? "" : "Required field" });
  };

  const handleTogglePassword = () => {
    if (formData.password) {
      setFormData({ ...formData, showPassword: !formData.showPassword });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let newErrors = {};
    if (!formData.regNumber) newErrors.regNumber = "Required field";
    if (!formData.password) newErrors.password = "Required field";
    setErrors(newErrors);
    if (Object.keys(newErrors).length === 0) {
      console.log("Login Successful", formData);
      navigate("/dashboard");
    }
  };

  return (
    <Box sx={{ minHeight: "100vh", background: "rgba(100, 200, 225, 0.3)", backdropFilter: "blur(15px)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
      <AppBar position="fixed" color="primary">
        <Toolbar>
          <Typography variant="h6">SRC E-Voting System</Typography>
        </Toolbar>
      </AppBar>
      <Container maxWidth="sm" sx={{ mt: 12 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            Login
          </Typography>
          <Box component="form" onSubmit={handleSubmit} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            <TextField label="Registration Number" name="regNumber" value={formData.regNumber} onChange={handleChange} required fullWidth helperText={errors.regNumber} error={!!errors.regNumber} />
            <TextField label="Password" name="password" type={formData.showPassword ? "text" : "password"} value={formData.password} onChange={handleChange} required fullWidth 
              InputProps={{
                endAdornment: (
                  formData.password && (
                    <InputAdornment position="end">
                      <IconButton onClick={handleTogglePassword} edge="end">
                        {formData.showPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    </InputAdornment>
                  )
                )
              }}
              helperText={errors.password} error={!!errors.password}
            />
            <FormControlLabel control={<Checkbox name="rememberMe" checked={formData.rememberMe} onChange={handleChange} />} label="Remember Me" />
            <Typography variant="body2" align="right">
              <a href="/forgot-password" style={{ color: "#1565c0", textDecoration: "none" }}>Forgot Password?</a>
            </Typography>
            <Button type="submit" variant="contained" color="success" fullWidth sx={{ height: "48px" }}>Login</Button>
            <Typography variant="body2" align="center" sx={{ mt: 2 }}>
              Don't have an account? <a href="/register" style={{ color: "#1565c0", textDecoration: "none" }}>Sign up</a>
            </Typography>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default Login;
